 5→import HIHOBridge from "@/components/HIHOBridge";
 6→import TriuneNav, { type TriuneMode } from "@/components/TriuneNav";
 7→import AnimaNarrationBar from "@/components/AnimaNarrationBar";
 8→import AnimaChatPanel from "@/components/AnimaChatPanel";
