10→import VaultMode from "@/components/modes/VaultMode";
11→import CockpitMode from "@/components/modes/CockpitMode";
12→
13→const MODE_CLASSES: Record<TriuneMode, string> = {
14→  knower: "mode-enter-knower",
15→  thinker: "mode-enter-thinker",
16→  doer: "mode-enter-doer",
17→};
18→
19→export default function Home() {
20→  return (
21→    <UniverseProvider>
22→      <AnimaDashboard />
23→    </UniverseProvider>
24→  );
25→}
