 1→import { useState, useEffect } from 'react';
 2→
 3→export interface ManifoldPoint {
 4→    trajectory_id: string;
 5→    coherence: number;
 6→    doer: number[];
 7→    thinker: number[];
 8→    knower: number[];
 9→}
10→
11→export function useManifold() {
12→    const [points, setPoints] = useState<ManifoldPoint[]>([]);
13→    const [latestPoint, setLatestPoint] = useState<ManifoldPoint | null>(null);
14→
15→    useEffect(() => {
16→        const ws = new WebSocket('ws://localhost:8080/telemetry');
17→
18→        ws.onopen = () => {
19→            console.log('Connected to Cohezion Telemetry');
20→        };
21→
22→        ws.onmessage = (event) => {
23→            try {
24→                const data = JSON.parse(event.data);
25→                const newPoint: ManifoldPoint = {
26→                    trajectory_id: data.trajectory_id,
27→                    coherence: data.coherence,
28→                    doer: data.state.doer,
29→                    thinker: data.state.thinker,
30→                    knower: data.state.knower
31→                };
32→                
33→                setLatestPoint(newPoint);
34→                setPoints(prev => {
35→                    const updated = [...prev, newPoint];
36→                    return updated.slice(-50); // Keep last 50 points
37→                });
38→            } catch (e) {
39→                console.warn('Failed to parse telemetry message:', e);
40→            }
41→        };
42→
43→        // Fallback Generator (Dream State)
44→        const interval = setInterval(() => {
45→            if (ws.readyState !== WebSocket.OPEN) {
46→                const dummyPoint: ManifoldPoint = {
47→                    trajectory_id: `dream_${Math.floor(Math.random() * 1000)}`,
48→                    coherence: 0.4 + Math.random() * 0.2,
49→                    doer: Array.from({ length: 12 }, () => Math.random() * 2 - 1),
50→                    thinker: Array.from({ length: 10 }, () => Math.random() * 2 - 1),
51→                    knower: Array.from({ length: 10 }, () => Math.random() * 2 - 1)
52→                };
53→                setLatestPoint(dummyPoint);
54→                setPoints(prev => [...prev, dummyPoint].slice(-50));
55→            }
56→        }, 2000);
57→
58→        return () => {
59→            ws.close();
60→            clearInterval(interval);
61→        };
62→    }, []);
63→
64→    return { points, latestPoint };
65→}
