 1→import { useEffect, useRef } from 'react';
 2→
 3→/**
 4→ * HIHO Sonification Engine - HomeostasisHarmonics
 5→ * 
 6→ * Maps 12D manifold stability to audio frequencies.
 7→ * Protocol: Map field transitions to audio frequencies based on distance from 0.5.
 8→ */
 9→export const useHomeostasisHarmonics = (coherence: number, active: boolean) => {
10→    const audioCtxRef = useRef<AudioContext | null>(null);
11→    const oscillatorRef = useRef<OscillatorNode | null>(null);
12→    const gainNodeRef = useRef<GainNode | null>(null);
13→
14→    useEffect(() => {
15→        if (!active) {
16→            if (audioCtxRef.current) {
17→                audioCtxRef.current.close();
18→                audioCtxRef.current = null;
19→            }
20→            return;
21→        }
22→
23→        if (!audioCtxRef.current) {
24→            audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
25→
26→            gainNodeRef.current = audioCtxRef.current.createGain();
27→            gainNodeRef.current.gain.value = 0.05; // Base volume
28→            gainNodeRef.current.connect(audioCtxRef.current.destination);
29→
30→            oscillatorRef.current = audioCtxRef.current.createOscillator();
31→            oscillatorRef.current.type = 'sine';
32→            oscillatorRef.current.connect(gainNodeRef.current);
33→            oscillatorRef.current.start();
34→        }
35→
36→        if (oscillatorRef.current && gainNodeRef.current && audioCtxRef.current) {
37→            // Mapping Logic:
38→            // 0.5 = Perfect stability = Neutral tone (440Hz)
39→            // Deviance from 0.5 = Higher/Lower frequencies
40→
41→            const distFromHIHO = Math.abs(coherence - 0.5);
42→            const frequency = 440 + (distFromHIHO * 200); // 440Hz to 540Hz mapping
43→
44→            const now = audioCtxRef.current.currentTime;
45→            oscillatorRef.current.frequency.exponentialRampToValueAtTime(frequency, now + 0.1);
46→
47→            // Volume modulation based on activity
48→            const volume = 0.05 + (distFromHIHO * 0.1);
49→            gainNodeRef.current.gain.linearRampToValueAtTime(volume, now + 0.1);
50→        }
51→    }, [coherence, active]);
52→};
